use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::thread;

fn main() -> std::io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:0")?;
    let addr = listener.local_addr()?;

    // a server that answers exactly one request
    let server = thread::spawn(move || -> std::io::Result<()> {
        let (stream, _peer) = listener.accept()?;
        let mut reader = BufReader::new(&stream);
        let mut request_line = String::new();
        reader.read_line(&mut request_line)?;
        loop {
            let mut header = String::new();
            reader.read_line(&mut header)?;
            if header == "\r\n" {
                break;
            }
        }
        let body = format!("you asked for {}", request_line.split(' ').nth(1).unwrap_or("?"));
        let mut stream = &stream;
        write!(stream, "HTTP/1.0 200 OK\r\nContent-Length: {}\r\n\r\n{}", body.len(), body)?;
        Ok(())
    });

    // the client, as in Rust in Action's ch8-stdlib
    let mut connection = TcpStream::connect(addr)?;
    connection.write_all(b"GET /hello HTTP/1.0")?;
    connection.write_all(b"\r\n")?;
    connection.write_all(b"Host: localhost")?;
    connection.write_all(b"\r\n\r\n")?;

    let mut response = String::new();
    connection.read_to_string(&mut response)?;
    print!("{}", response.replace("\r\n", "\n"));
    println!();

    server.join().unwrap()?;
    Ok(())
}

use std::net::{IpAddr, Ipv4Addr, SocketAddr, ToSocketAddrs};

fn main() -> std::io::Result<()> {
    let addr: SocketAddr = "192.168.1.20:8080".parse().unwrap();
    println!("ip {} port {} v4? {}", addr.ip(), addr.port(), addr.is_ipv4());

    let local = IpAddr::V4(Ipv4Addr::LOCALHOST);
    println!("{local} loopback? {}", local.is_loopback());
    println!("{}", "10.0.0.1".parse::<Ipv4Addr>().unwrap().is_private());
    println!("{:?}", "999.1.1.1".parse::<Ipv4Addr>().is_err());

    // name resolution through the operating system
    let v4: Vec<SocketAddr> = "localhost:80".to_socket_addrs()?.filter(|a| a.is_ipv4()).collect();
    println!("{v4:?}");
    Ok(())
}

use std::net::UdpSocket;
use std::time::Duration;

fn main() -> std::io::Result<()> {
    let server = UdpSocket::bind("127.0.0.1:0")?;
    let client = UdpSocket::bind("127.0.0.1:0")?;
    client.set_read_timeout(Some(Duration::from_secs(2)))?;

    client.send_to(b"ping", server.local_addr()?)?;

    let mut buf = [0u8; 512];
    let (n, from) = server.recv_from(&mut buf)?;
    println!("server got {:?}", String::from_utf8_lossy(&buf[..n]));
    server.send_to(b"pong", from)?;

    let (n, _) = client.recv_from(&mut buf)?;
    println!("client got {:?}", String::from_utf8_lossy(&buf[..n]));
    Ok(())
}

